enum anim_flags_t { ANIM_RELATIVE_TO_START = 0x20, ANIM_WAS_LOOPED = 0x400 };
class anim_control_t { float current_time,time_delta,duration,timescale_factor,cntrl_tween_duration,tween_timer; unsigned flags; short loop_count; public: bool was_looped() const { return flags & ANIM_WAS_LOOPED; } };
struct vector3d { float x,y,z; vector3d() {} vector3d(float X,float Y,float Z):x(X),y(Y),z(Z){} vector3d& operator=(const vector3d& v){x=v.x;y=v.y;z=v.z;return *this;} };
inline vector3d operator+(const vector3d&a,const vector3d&b){return vector3d(a.x+b.x,a.y+b.y,a.z+b.z);}
struct quaternion { float x,y,z,w; quaternion operator*(const quaternion&) const; quaternion& operator=(const quaternion&q){x=q.x;y=q.y;z=q.z;w=q.w;return *this;} };
template<class T> class anim { protected: unsigned short flags; public: virtual void set_flag(anim_flags_t); virtual void clear_flag(anim_flags_t); virtual void set_flag(anim_flags_t,bool); virtual void set_time(float); virtual void frame_advance(const anim_control_t&,T*); virtual void get_value(const anim_control_t&,T*)const; virtual void get_value(float,T*)const; bool is_valid()const{return flags&0x1000;} };
inline vector3d anim_xform3d_1(const vector3d *rot, const vector3d &sv){vector3d res;res.x=rot[0].x*sv.x+rot[1].x*sv.y+rot[2].x*sv.z;res.y=rot[0].y*sv.x+rot[1].y*sv.y+rot[2].y*sv.z;res.z=rot[0].z*sv.x+rot[1].z*sv.y+rot[2].z*sv.z;return res;}
class po;
class po_anim:public anim<po>{anim<vector3d>*P;anim<quaternion>*R;anim<float>*S;vector3d P_start;quaternion R_start;float S_start;vector3d R_start_mat[3];public:bool has_P()const{return P&&P->is_valid();}bool has_R()const{return R&&R->is_valid();}bool has_S()const{return S&&S->is_valid();}bool is_relative_to_start()const{return flags&ANIM_RELATIVE_TO_START;}void reset_start_for_loop(const anim_control_t&);void frame_advance(const anim_control_t&,vector3d&,quaternion&,float&);};
void po_anim::frame_advance( const anim_control_t& ac, vector3d &p, quaternion &r, float &s )
{
  if ( ac.was_looped() && is_relative_to_start() )
  {
    reset_start_for_loop( ac );
  }
  if ( has_P() )
  {
    P->frame_advance( ac, &p );
    if ( is_relative_to_start() )
    {
      p = anim_xform3d_1(&R_start_mat[0],p) + P_start;
    }
  }
  else
    p = P_start;
  if ( has_R() )
  {
    R->frame_advance( ac, &r );
    if ( is_relative_to_start() )
      r = r * R_start;
  }
  else
    r = R_start;
  if ( has_S() )
  {
    S->frame_advance( ac, &s );
    if ( is_relative_to_start() )
      s *= S_start;
  }
  else
    s = S_start;
}
